33	export interface StartSessionResult {
34	  sessionId?: string;
35	  error?: string;
36	}
37	
38	/**
39	 * Start (or re-join) the mock call for a booking. Idempotent: returns the
40	 * existing session if one already exists. Creates the call session via the
41	 * calls adapter and the sessions row via the service-role client.
42	 */
43	export async function startSession(
44	  bookingId: string,
45	): Promise<StartSessionResult> {
46	  const booking = await loadBookingForParty(bookingId);
47	  if (!booking) return { error: "This session isn't available." };
48	
49	  // A suspended customer cannot start a call (safety: protects providers).
50	  const profile = await getProfile();
51	  if (profile?.id === booking.customer_id && profile.is_suspended) {
52	    return { error: "Your account is paused. Please contact support." };
53	  }
54	
55	  const supabase = await createClient();
56	  const { data: existing } = await supabase
57	    .from("sessions")
58	    .select("id")
59	    .eq("booking_id", bookingId)
60	    .maybeSingle();
61	  if (existing) return { sessionId: existing.id };
62	
63	  const calls = getCalls();
64	  const { callSessionRef } = await calls.createSession({
65	    bookingId,
66	    providerId: booking.provider_id,
67	    customerId: booking.customer_id,
68	    maxMinutes: booking.block_minutes + 15,
69	  });
70	
71	  const admin = createAdminClient();
72	  const { data: session, error } = await admin
73	    .from("sessions")
74	    .insert({
75	      booking_id: bookingId,
76	      provider_id: booking.provider_id,
77	      customer_id: booking.customer_id,
78	      call_session_ref: callSessionRef,
79	      started_at: new Date().toISOString(),
80	      block_minutes: booking.block_minutes,
81	      status: "in_progress",
82	    })
83	    .select("id")
84	    .single();
85	  if (error || !session) return { error: "We couldn't start the call." };
86	
87	  await supabase
88	    .from("bookings")
89	    .update({ status: "in_progress" })
90	    .eq("id", bookingId);
91	
92	  return { sessionId: session.id };
93	}
